-- script: main
-- velox:lock-timeout 5s

-- review: add-identity: adds an identity to column users.id and sets its counter past the column's largest value; serial-to-identity: turns serial column users.id into an identity that goes on from its sequence: its default and sequence are dropped
ALTER TABLE "users" ALTER COLUMN "id" DROP DEFAULT;
ALTER SEQUENCE "users_id_seq" OWNED BY NONE;
ALTER SEQUENCE "users_id_seq" RENAME TO "users_id_seq_velox_old";
ALTER TABLE "users" ALTER COLUMN "id" ADD GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "users_id_seq");
SELECT setval(pg_get_serial_sequence('"users"', 'id'), greatest(coalesce(max("id"), 0) + 1, (SELECT CASE WHEN is_called THEN last_value + 1 ELSE last_value END FROM "users_id_seq_velox_old")), false) FROM "users";
DROP SEQUENCE "users_id_seq_velox_old";
